// swift-tools-version: 6.1
import PackageDescription

let package = Package(
    name: "LRU",
    products: [.executable(name: "app", targets: ["app"])],
    targets: [
        .target(name: "LRUCore"),
        .executableTarget(name: "app", dependencies: ["LRUCore"]),
        .testTarget(name: "LRUCoreTests", dependencies: ["LRUCore"]),
    ]
)

/// Interprets the line-oriented LRU command language and accumulates output.
public struct CommandProcessor {
    private var cache: LRUCache<String, String>
    public private(set) var output = ""

    public init(capacity: Int) {
        cache = LRUCache(capacity: capacity)
    }

    /// Executes one command line. Blank or unrecognised lines are ignored.
    public mutating func execute(_ line: Substring) {
        let tokens = line.split(separator: " ", omittingEmptySubsequences: true)
        guard let command = tokens.first else { return }
        switch (command, tokens.count) {
        case ("SET", 3):
            cache.set(String(tokens[1]), String(tokens[2]))
        case ("GET", 2):
            emit(cache.get(String(tokens[1])) ?? "NULL")
        case ("DEL", 2):
            emit(cache.remove(String(tokens[1])) ? "1" : "0")
        case ("SIZE", 1):
            emit(String(cache.count))
        default:
            break
        }
    }

    private mutating func emit(_ text: some StringProtocol) {
        output += text
        output += "\n"
    }
}

extension CommandProcessor {
    /// Runs a complete program: the first line is the capacity, the rest are commands.
    /// Returns `nil` if the capacity line is missing or invalid.
    public static func run(lines: some Sequence<Substring>) -> String? {
        var iterator = lines.makeIterator()
        guard let first = iterator.next(),
              let capacity = Int(first.trimmingWhitespace()),
              capacity >= 1
        else { return nil }
        var processor = CommandProcessor(capacity: capacity)
        while let line = iterator.next() {
            processor.execute(line)
        }
        return processor.output
    }
}

extension Substring {
    func trimmingWhitespace() -> Substring {
        let isSpace: (Character) -> Bool = { $0 == " " || $0 == "\t" || $0 == "\r" }
        let start = firstIndex { !isSpace($0) } ?? endIndex
        let end = lastIndex { !isSpace($0) }.map(index(after:)) ?? start
        return self[start..<end]
    }
}

/// A fixed-capacity cache that evicts the least recently used entry.
///
/// Entries live in a contiguous node pool linked into a doubly linked
/// recency list by index, so every operation runs in O(1) expected time
/// without per-entry heap allocations for the list itself.
public struct LRUCache<Key: Hashable, Value> {
    private struct Node {
        var key: Key
        var value: Value
        var prev: Int
        var next: Int
    }

    private static var none: Int { -1 }

    public let capacity: Int
    private var nodes: [Node] = []
    private var freeSlots: [Int] = []
    private var index: [Key: Int] = [:]
    /// Most recently used node.
    private var head = LRUCache.none
    /// Least recently used node.
    private var tail = LRUCache.none

    /// Creates an empty cache. `capacity` must be at least 1.
    public init(capacity: Int) {
        precondition(capacity >= 1, "LRUCache capacity must be at least 1")
        self.capacity = capacity
        let initial = Swift.min(capacity, 1 << 16)
        nodes.reserveCapacity(initial)
        index.reserveCapacity(initial)
    }

    /// The number of entries currently held.
    public var count: Int { index.count }

    /// Returns the value for `key`, marking it most recently used on a hit.
    public mutating func get(_ key: Key) -> Value? {
        guard let slot = index[key] else { return nil }
        moveToFront(slot)
        return nodes[slot].value
    }

    /// Inserts or overwrites `key`, marking it most recently used and
    /// evicting the least recently used entry if capacity is exceeded.
    public mutating func set(_ key: Key, _ value: Value) {
        if let slot = index[key] {
            nodes[slot].value = value
            moveToFront(slot)
            return
        }
        let slot = allocate(Node(key: key, value: value, prev: Self.none, next: Self.none))
        index[key] = slot
        linkAtFront(slot)
        if index.count > capacity {
            remove(slot: tail)
        }
    }

    /// Removes `key`. Returns `true` if it was present.
    @discardableResult
    public mutating func remove(_ key: Key) -> Bool {
        guard let slot = index[key] else { return false }
        remove(slot: slot)
        return true
    }

    // MARK: - Private

    private mutating func allocate(_ node: Node) -> Int {
        if let slot = freeSlots.popLast() {
            nodes[slot] = node
            return slot
        }
        nodes.append(node)
        return nodes.count - 1
    }

    private mutating func remove(slot: Int) {
        unlink(slot)
        index.removeValue(forKey: nodes[slot].key)
        freeSlots.append(slot)
    }

    private mutating func moveToFront(_ slot: Int) {
        guard slot != head else { return }
        unlink(slot)
        linkAtFront(slot)
    }

    private mutating func linkAtFront(_ slot: Int) {
        nodes[slot].prev = Self.none
        nodes[slot].next = head
        if head != Self.none {
            nodes[head].prev = slot
        } else {
            tail = slot
        }
        head = slot
    }

    private mutating func unlink(_ slot: Int) {
        let prev = nodes[slot].prev
        let next = nodes[slot].next
        if prev != Self.none {
            nodes[prev].next = next
        } else {
            head = next
        }
        if next != Self.none {
            nodes[next].prev = prev
        } else {
            tail = prev
        }
        nodes[slot].prev = Self.none
        nodes[slot].next = Self.none
    }
}

import LRUCore

/// Lazily reads standard input line by line, stripping a trailing carriage return.
struct StandardInputLines: Sequence, IteratorProtocol {
    mutating func next() -> Substring? {
        guard var line = readLine(strippingNewline: true) else { return nil }
        if line.hasSuffix("\r") { line.removeLast() }
        return Substring(line)
    }
}

if let output = CommandProcessor.run(lines: StandardInputLines()) {
    print(output, terminator: "")
}

import Testing
@testable import LRUCore

@Suite struct LRUCacheTests {
    @Test func evictsLeastRecentlyUsed() {
        var cache = LRUCache<String, Int>(capacity: 2)
        cache.set("a", 1)
        cache.set("b", 2)
        #expect(cache.get("a") == 1)
        cache.set("c", 3)
        #expect(cache.get("b") == nil)
        #expect(cache.count == 2)
    }

    @Test func overwriteRefreshesRecency() {
        var cache = LRUCache<String, Int>(capacity: 2)
        cache.set("a", 1)
        cache.set("b", 2)
        cache.set("a", 9)
        cache.set("c", 3)
        #expect(cache.get("a") == 9)
        #expect(cache.get("b") == nil)
    }

    @Test func removeReportsPresenceAndReusesSlots() {
        var cache = LRUCache<String, Int>(capacity: 1)
        cache.set("x", 1)
        #expect(cache.remove("x"))
        #expect(!cache.remove("x"))
        #expect(cache.count == 0)
        cache.set("y", 2)
        #expect(cache.get("y") == 2)
    }
}

@Suite struct CommandProcessorTests {
    @Test func specExample() {
        let input = "2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE"
        let output = CommandProcessor.run(lines: input.split(separator: "\n", omittingEmptySubsequences: false))
        #expect(output == "1\nNULL\n2\n")
    }
}
